'use strict';

const { SerialPort } = require('serialport');
const { execFile } = require('child_process');
const { promisify } = require('util');
const {
  buildAbsoluteMousePayload,
  buildCmdPacket,
  buildRelativeMousePayload,
  CMD_SEND_MS_ABS_DATA,
  CMD_SEND_MS_REL_DATA
} = require('../lib/protocol');

const execFileAsync = promisify(execFile);

function sleep(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

function parseArgs(argv) {
  const options = {
    portPath: process.env.CH9329_PORT || process.env.THIFLOW_ROBOT_PORT || '/dev/cu.usbserial-130',
    baudRate: Number(process.env.CH9329_BAUD_RATE || 9600),
    button: process.env.CH9329_MOUSE_BUTTON || 'left',
    variant: process.env.CH9329_MOUSE_VARIANT || 'standard',
    holdMs: Number(process.env.CH9329_MOUSE_HOLD_MS || 500),
    repeat: Number(process.env.CH9329_MOUSE_REPEAT || 1),
    intervalMs: Number(process.env.CH9329_MOUSE_INTERVAL_MS || 500)
  };

  for (let index = 0; index < argv.length; index += 1) {
    const arg = argv[index];
    const next = argv[index + 1];

    if (arg === '--port' && next) {
      options.portPath = next;
      index += 1;
    } else if (arg === '--baud' && next) {
      options.baudRate = Number(next);
      index += 1;
    } else if (arg === '--button' && next) {
      options.button = next;
      index += 1;
    } else if (arg === '--variant' && next) {
      options.variant = next;
      index += 1;
    } else if (arg === '--hold-ms' && next) {
      options.holdMs = Number(next);
      index += 1;
    } else if (arg === '--repeat' && next) {
      options.repeat = Number(next);
      index += 1;
    } else if (arg === '--interval-ms' && next) {
      options.intervalMs = Number(next);
      index += 1;
    } else if (arg === '--help' || arg === '-h') {
      options.help = true;
    } else {
      throw new Error(`Unknown argument: ${arg}`);
    }
  }

  if (!['left', 'right', 'middle'].includes(options.button)) {
    throw new Error('--button must be left, right, or middle');
  }

  if (!['standard', 'nudge', 'absolute-current', 'absolute-zero', 'no-report-id', 'all'].includes(options.variant)) {
    throw new Error('--variant must be standard, nudge, absolute-current, absolute-zero, no-report-id, or all');
  }

  for (const key of ['baudRate', 'holdMs', 'repeat', 'intervalMs']) {
    if (!Number.isFinite(options[key]) || options[key] < 0) {
      throw new Error(`--${key} must be a non-negative number`);
    }
  }

  options.baudRate = Math.round(options.baudRate);
  options.holdMs = Math.round(options.holdMs);
  options.repeat = Math.max(1, Math.round(options.repeat));
  options.intervalMs = Math.round(options.intervalMs);

  return options;
}

function printHelp() {
  console.log([
    'Usage: node demos/ch9329-raw-mouse.js --port /dev/cu.usbserial-130 --variant standard|nudge|absolute-current|absolute-zero|no-report-id|all',
    '',
    'Variants:',
    '  standard      CH9329 documented relative mouse report: [0x01, button, 0, 0, 0]',
    '  nudge         Same as standard, but moves +1px while pressed and -1px on release',
    '  absolute-current  CH9329 documented absolute mouse report at the current macOS cursor point',
    '  absolute-zero     CH9329 documented absolute mouse click example with x=0,y=0',
    '  no-report-id  Test older/alternate layout: [button, 0, 0, 0, 0]',
    '  all           Try the common variants with pauses between them'
  ].join('\n'));
}

function buttonMask(button) {
  if (button === 'right') return 0x02;
  if (button === 'middle') return 0x04;
  return 0x01;
}

function toHex(buffer) {
  return Buffer.from(buffer).toString('hex').match(/../g).join(' ');
}

async function getMacCursorAndScreen() {
  if (process.platform !== 'darwin') {
    return null;
  }

  const { stdout } = await execFileAsync('swift', [
    '-e',
    [
      'import AppKit',
      'let p = NSEvent.mouseLocation',
      'let screens = NSScreen.screens',
      'let screen = screens.first(where: { NSMouseInRect(p, $0.frame, false) }) ?? screens.first',
      'if let s = screen {',
      '  let f = s.frame',
      '  let x = Int(p.x - f.minX)',
      '  let y = Int(f.maxY - p.y)',
      '  print("\\(x),\\(y),\\(Int(f.width)),\\(Int(f.height))")',
      '} else {',
      '  print("0,0,1,1")',
      '}'
    ].join('\n')
  ]);
  const [x, y, width, height] = stdout.trim().split(',').map((value) => Number(value));
  if ([x, y, width, height].every((value) => Number.isFinite(value))) {
    return { x, y, width, height };
  }
  return null;
}

async function buildVariantPackets(variant, mask) {
  if (variant === 'nudge') {
    return [
      buildCmdPacket(CMD_SEND_MS_REL_DATA, buildRelativeMousePayload(mask, 1, 0, 0)),
      buildCmdPacket(CMD_SEND_MS_REL_DATA, buildRelativeMousePayload(0, -1, 0, 0))
    ];
  }

  if (variant === 'absolute-current') {
    const point = await getMacCursorAndScreen();
    if (!point) {
      throw new Error('absolute-current is currently implemented for macOS cursor sampling only');
    }
    console.log(`[raw-mouse] absolute-current point=${JSON.stringify(point)}`);
    return [
      buildCmdPacket(
        CMD_SEND_MS_ABS_DATA,
        buildAbsoluteMousePayload(mask, point.x, point.y, point.width, point.height)
      ),
      buildCmdPacket(
        CMD_SEND_MS_ABS_DATA,
        buildAbsoluteMousePayload(0, point.x, point.y, point.width, point.height)
      )
    ];
  }

  if (variant === 'absolute-zero') {
    return [
      buildCmdPacket(CMD_SEND_MS_ABS_DATA, buildAbsoluteMousePayload(mask, 0, 0, 4096, 4096)),
      buildCmdPacket(CMD_SEND_MS_ABS_DATA, buildAbsoluteMousePayload(0, 0, 0, 4096, 4096))
    ];
  }

  if (variant === 'no-report-id') {
    return [
      buildCmdPacket(CMD_SEND_MS_REL_DATA, [mask, 0, 0, 0, 0]),
      buildCmdPacket(CMD_SEND_MS_REL_DATA, [0, 0, 0, 0, 0])
    ];
  }

  return [
    buildCmdPacket(CMD_SEND_MS_REL_DATA, buildRelativeMousePayload(mask, 0, 0, 0)),
    buildCmdPacket(CMD_SEND_MS_REL_DATA, buildRelativeMousePayload(0, 0, 0, 0))
  ];
}

async function openPort(options) {
  const port = new SerialPort({
    path: options.portPath,
    baudRate: options.baudRate,
    autoOpen: false
  });

  port.on('data', (data) => {
    console.log(`[raw-mouse] rx ${toHex(data)}`);
  });

  await new Promise((resolve, reject) => {
    port.open((error) => {
      if (error) reject(error);
      else resolve();
    });
  });

  return port;
}

async function writePacket(port, packet) {
  console.log(`[raw-mouse] tx ${toHex(packet)}`);
  await new Promise((resolve, reject) => {
    port.write(packet, (error) => {
      if (error) {
        reject(error);
        return;
      }
      port.drain((drainError) => {
        if (drainError) reject(drainError);
        else resolve();
      });
    });
  });
}

async function closePort(port) {
  await new Promise((resolve) => {
    port.close(() => resolve());
  });
}

async function runVariant(port, options, variant) {
  const mask = buttonMask(options.button);
  const [pressPacket, releasePacket] = await buildVariantPackets(variant, mask);

  console.log(`[raw-mouse] variant=${variant} button=${options.button} repeat=${options.repeat} holdMs=${options.holdMs}`);
  for (let index = 0; index < options.repeat; index += 1) {
    await writePacket(port, pressPacket);
    await sleep(options.holdMs);
    await writePacket(port, releasePacket);
    if (index < options.repeat - 1) {
      await sleep(options.intervalMs);
    }
  }
}

async function main() {
  const options = parseArgs(process.argv.slice(2));
  if (options.help) {
    printHelp();
    return;
  }

  const variants = options.variant === 'all'
    ? ['standard', 'nudge', 'absolute-current', 'no-report-id']
    : [options.variant];

  console.log(`[raw-mouse] open ${options.portPath} @ ${options.baudRate}`);
  const port = await openPort(options);
  try {
    for (const variant of variants) {
      console.log(`[raw-mouse] 3s 后测试 ${variant}，请把鼠标放到明显可点击位置...`);
      await sleep(3000);
      await runVariant(port, options, variant);
      await sleep(options.intervalMs);
    }
  } finally {
    await closePort(port);
    console.log('[raw-mouse] closed');
  }
}

main().catch((error) => {
  console.error('[raw-mouse] failed:', error);
  process.exitCode = 1;
});
